"use client";

import type React from "react";

import { useState } from "react";
import { useParams } from "next/navigation";
import { useFormsStore } from "@/lib/forms-store";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { CheckCircle2, Upload } from "lucide-react";
import type { Field } from "@/types";

export default function PublicFormPage() {
  const params = useParams<{ id: string }>();
  const { id } = params;
  const { getFormById, addSubmission } = useFormsStore();

  const form = getFormById(id);
  const [answers, setAnswers] = useState<Record<string, string | string[]>>({});
  const [submitted, setSubmitted] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  if (!form) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-xl font-semibold text-foreground mb-2">
            Form not found
          </h2>
          <p className="text-muted-foreground">
            This form does not exist or has been deleted.
          </p>
        </div>
      </div>
    );
  }

  if (form.status === "draft") {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-xl font-semibold text-foreground mb-2">
            Form not published
          </h2>
          <p className="text-muted-foreground">
            This form is not yet published.
          </p>
        </div>
      </div>
    );
  }

  const handleFieldChange = (fieldId: string, value: string | string[]) => {
    setAnswers({ ...answers, [fieldId]: value });
    if (errors[fieldId]) {
      setErrors({ ...errors, [fieldId]: "" });
    }
  };

  const handleCheckboxChange = (
    fieldId: string,
    option: string,
    checked: boolean
  ) => {
    const currentValues = (answers[fieldId] as string[]) || [];
    const newValues = checked
      ? [...currentValues, option]
      : currentValues.filter((v) => v !== option);
    handleFieldChange(fieldId, newValues);
  };

  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    form.content.forEach((section) => {
      section.fields.forEach((field) => {
        if (field.required) {
          const answer = answers[field.id];
          if (
            !answer ||
            (Array.isArray(answer) && answer.length === 0) ||
            answer === ""
          ) {
            newErrors[field.id] = "This field is required";
          }
        }

        if (field.type === "email" && answers[field.id]) {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(answers[field.id] as string)) {
            newErrors[field.id] = "Please enter a valid email address";
          }
        }

        if (field.type === "url" && answers[field.id]) {
          try {
            new URL(answers[field.id] as string);
          } catch {
            newErrors[field.id] = "Please enter a valid URL";
          }
        }

        if (field.type === "number" && answers[field.id]) {
          const num = Number.parseFloat(answers[field.id] as string);
          if (field.min !== undefined && num < field.min) {
            newErrors[field.id] = `Value must be at least ${field.min}`;
          }
          if (field.max !== undefined && num > field.max) {
            newErrors[field.id] = `Value must be at most ${field.max}`;
          }
        }
      });
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    addSubmission({
      formId: id,
      answers,
    });

    setSubmitted(true);
  };

  const renderField = (field: Field) => {
    const hasError = !!errors[field.id];

    switch (field.type) {
      case "text":
      case "email":
      case "url":
      case "date":
      case "time":
        return (
          <Input
            type={field.type}
            placeholder={field.placeholder}
            value={(answers[field.id] as string) || ""}
            onChange={(e) => handleFieldChange(field.id, e.target.value)}
            className={hasError ? "border-destructive" : ""}
          />
        );

      case "number":
        return (
          <Input
            type="number"
            placeholder={field.placeholder}
            value={(answers[field.id] as string) || ""}
            onChange={(e) => handleFieldChange(field.id, e.target.value)}
            min={field.min}
            max={field.max}
            className={hasError ? "border-destructive" : ""}
          />
        );

      case "textarea":
        return (
          <Textarea
            placeholder={field.placeholder}
            value={(answers[field.id] as string) || ""}
            onChange={(e) => handleFieldChange(field.id, e.target.value)}
            rows={5} // Increased default rows
            className={`min-h-[150px] resize-y ${
              hasError ? "border-destructive" : ""
            }`} // Added min-height
          />
        );

      case "select":
        return (
          <Select
            value={(answers[field.id] as string) || ""}
            onValueChange={(value) => handleFieldChange(field.id, value)}
          >
            <SelectTrigger className={hasError ? "border-destructive" : ""}>
              <SelectValue placeholder="Select an option..." />
            </SelectTrigger>
            <SelectContent>
              {field.options?.map((option) => (
                <SelectItem key={option} value={option}>
                  {option}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        );

      case "radio":
        return (
          <RadioGroup
            value={(answers[field.id] as string) || ""}
            onValueChange={(value) => handleFieldChange(field.id, value)}
          >
            {field.options?.map((option) => (
              <div key={option} className="flex items-center space-x-2">
                <RadioGroupItem value={option} id={`${field.id}-${option}`} />
                <Label
                  htmlFor={`${field.id}-${option}`}
                  className="font-normal cursor-pointer"
                >
                  {option}
                </Label>
              </div>
            ))}
          </RadioGroup>
        );

      case "checkbox":
        return (
          <div className="space-y-2">
            {field.options?.map((option) => (
              <div key={option} className="flex items-center space-x-2">
                <Checkbox
                  id={`${field.id}-${option}`}
                  checked={((answers[field.id] as string[]) || []).includes(
                    option
                  )}
                  onCheckedChange={(checked) =>
                    handleCheckboxChange(field.id, option, checked as boolean)
                  }
                />
                <Label
                  htmlFor={`${field.id}-${option}`}
                  className="font-normal cursor-pointer"
                >
                  {option}
                </Label>
              </div>
            ))}
          </div>
        );

      case "upload":
        return (
          <div className="space-y-2">
            <div
              className={`border rounded-md px-3 py-2 bg-background flex items-center gap-2 ${
                hasError ? "border-destructive" : "border-input"
              }`}
            >
              <Upload className="w-4 h-4 text-muted-foreground" />
              <Input
                type="file"
                className="border-0 p-0 h-auto shadow-none file:bg-secondary file:text-secondary-foreground file:border-0 file:rounded-md file:mr-4 file:px-2 file:text-sm cursor-pointer"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    // In a real app, you would upload to S3/Blob storage here
                    // For this demo, we just store the filename
                    handleFieldChange(field.id, file.name);
                  }
                }}
              />
            </div>
            {answers[field.id] && (
              <p className="text-xs text-muted-foreground flex items-center gap-1">
                File selected:{" "}
                <span className="font-medium text-foreground">
                  {answers[field.id]}
                </span>
              </p>
            )}
          </div>
        );

      default:
        return null;
    }
  };

  if (submitted) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-6">
        <div className="max-w-md w-full text-center">
          <div className="bg-card border border-border rounded-lg p-8 shadow-sm">
            <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4">
              <CheckCircle2 className="w-8 h-8 text-primary" />
            </div>
            <h2 className="text-2xl font-semibold text-foreground mb-2">
              Thank you!
            </h2>
            <p className="text-muted-foreground mb-6">
              Your response has been submitted successfully.
            </p>
            <Button onClick={() => setSubmitted(false)} variant="outline">
              Submit Another Response
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background py-12 px-6">
      <div className="max-w-2xl mx-auto">
        <div className="bg-card border border-border rounded-lg overflow-hidden shadow-sm">
          <div className="bg-muted/30 p-8 border-b border-border">
            <h1 className="text-3xl font-bold text-foreground mb-2">
              {form.title}
            </h1>
            {form.description && (
              <p className="text-muted-foreground text-lg">
                {form.description}
              </p>
            )}
          </div>

          <form onSubmit={handleSubmit} className="p-8">
            <div className="space-y-8">
              {form.content.map((section, sectionIndex) => (
                <div key={section.id}>
                  {sectionIndex > 0 && (
                    <div className="border-t border-border -mx-8 mb-8" />
                  )}

                  <h2 className="text-xl font-semibold text-foreground mb-6">
                    {section.title}
                  </h2>

                  {section.description && (
                    <p className="text-muted-foreground mb-6 -mt-4">
                      {section.description}
                    </p>
                  )}

                  <div className="space-y-6">
                    {section.fields.map((field) => (
                      <div key={field.id} className="space-y-2">
                        <Label
                          htmlFor={field.id}
                          className="text-base font-medium"
                        >
                          {field.title}
                          {field.required && (
                            <span className="text-destructive ml-1">*</span>
                          )}
                        </Label>
                        {field.description && (
                          <p className="text-sm text-muted-foreground">
                            {field.description}
                          </p>
                        )}
                        {renderField(field)}
                        {errors[field.id] && (
                          <p className="text-sm text-destructive font-medium">
                            {errors[field.id]}
                          </p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-8 pt-6 border-t border-border">
              <Button type="submit" size="lg" className="w-full text-base">
                Submit
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
